    assert_eq!(r["Attributes"]["MaxMessageBytes"], 1);
    let r = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "r"}));
    assert_eq!(r["Attributes"]["MaxMessageBytes"], 1024);
}

