        "Body": "abc", "GroupId": "g"}));
    assert_eq!(code, "InvalidParameterValue");
    let code = h.err(json!({"Command": "SendMessage", "QueueName": "nope",
        "Body": "x".repeat(1025)}));
    assert_eq!(code, "InvalidParameterValue");
}

