        json!({"a": 1}),
        json!({"a": null}),
        json!({"a": "x".repeat(257)}),
        json!({"a": "\u{20ac}".repeat(86)}),
    ] {
        assert_eq!(tag(&mut h, bad.clone())["error"]["code"], "InvalidParameterValue", "{bad}");
    }
    assert_eq!(tags(&mut h), json!({}));
